import{_ as a,o as s,c as t,a2 as r}from"./chunks/framework.DqYch1Cg.js";const u=JSON.parse('{"title":"发布、验证与回滚","description":"","frontmatter":{},"headers":[],"relativePath":"概念与原理/20deploy/s_deploy_5-release.md","filePath":"概念与原理/20deploy/s_deploy_5-release.md","lastUpdated":1794211306000}'),n={name:"概念与原理/20deploy/s_deploy_5-release.md"};function o(l,e,i,p,d,c){return s(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="发布、验证与回滚" tabindex="-1">发布、验证与回滚 <a class="header-anchor" href="#发布、验证与回滚" aria-label="Permalink to &quot;发布、验证与回滚&quot;">​</a></h1><h2 id="交付的是版本-不是一个目录" tabindex="-1">交付的是版本，不是一个目录 <a class="header-anchor" href="#交付的是版本-不是一个目录" aria-label="Permalink to &quot;交付的是版本，不是一个目录&quot;">​</a></h2><p>可重复的发布需要固定源码提交、运行时版本和依赖锁文件。构建产物与版本关联，测试环境和生产环境使用同一份已验证产物，再注入各自配置。不要在服务器随手改文件后忘记回仓库。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>源码版本 → 锁定依赖 → 检查与测试 → 构建产物</span></span>
<span class="line"><span>         → 部署候选版本 → 就绪检查 → 切换流量</span></span>
<span class="line"><span>         → 验证指标 → 保留旧版本 / 回滚</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>本项目是静态文档站：开发在 dev，发布以 main 为入口，由现有 GitHub Actions 构建 Pages。学习笔记新增内容不需要引入新的发布服务。后端应用还需管理进程、迁移、配置和依赖服务，不能直接套用静态站方案。</p><h2 id="发布前回答四个问题" tabindex="-1">发布前回答四个问题 <a class="header-anchor" href="#发布前回答四个问题" aria-label="Permalink to &quot;发布前回答四个问题&quot;">​</a></h2><ol><li><strong>发布什么？</strong> 提交号、产物校验、依赖和运行时版本可追踪。</li><li><strong>如何证明可用？</strong> lint / 类型 / 单元测试之外，还要验证入口、静态资源、关键接口、鉴权和数据库访问。</li><li><strong>怎样观察异常？</strong> 错误率、延迟分位数、数据库连接、资源占用，配合 requestId 和版本号串联日志。</li><li><strong>怎样回退？</strong> 旧产物仍可取、旧版本兼容当前配置与数据库，明确执行人及触发条件。</li></ol><h2 id="数据库变更与代码发布" tabindex="-1">数据库变更与代码发布 <a class="header-anchor" href="#数据库变更与代码发布" aria-label="Permalink to &quot;数据库变更与代码发布&quot;">​</a></h2><p>回滚代码不会撤销已写入的数据。优先使用 expand-contract：先增加兼容字段 / 接口，发布兼容读写版本，完成回填与验证，最后另一个窗口删除旧结构。耗时 DDL、索引构建和长事务要单独评估锁与超时。</p><p>PostgreSQL 的部分 DDL 可事务回滚，不等于所有迁移都低风险；<code>CREATE INDEX CONCURRENTLY</code> 等操作还有事务块限制。备份也需要经过恢复演练，确认恢复时间和可接受的数据丢失窗口。</p><h2 id="环境、日志与失败演练" tabindex="-1">环境、日志与失败演练 <a class="header-anchor" href="#环境、日志与失败演练" aria-label="Permalink to &quot;环境、日志与失败演练&quot;">​</a></h2><p>配置按环境注入，启动时检查必要配置是否存在；日志不输出口令、完整令牌或敏感请求体。限制日志大小并建立轮转，避免“程序正常、磁盘满了”。</p><p>可在隔离练习环境验证：应用启动失败、代理连不上上游、数据库短暂不可用、发布中断、回滚后读取新数据。记录现象、定位依据和恢复步骤；只有真的运行过才能写“已验证”。</p><p><strong>自测：</strong> 为什么“部署成功”不等于“发布成功”？为什么回滚旧镜像可能仍无法恢复？readiness 失败和 liveness 失败应采取相同动作吗？</p><blockquote><p>来源：<a href="https://github.com/Fridolph/Fridolph/tree/c3a1eda8e0f7fe08d8ec54e07d07db514cbfc5d7/%E9%83%A8%E7%BD%B2%E7%9B%B8%E5%85%B3%E7%9F%A5%E8%AF%86" target="_blank" rel="noreferrer">个人部署大纲</a>；<a href="https://docs.github.com/en/pages/getting-started-with-github-pages/using-custom-workflows-with-github-pages" target="_blank" rel="noreferrer">GitHub Pages 自定义工作流</a>；<a href="https://www.postgresql.org/docs/current/backup.html" target="_blank" rel="noreferrer">PostgreSQL 备份与恢复</a>。</p></blockquote>`,15)])])}const b=a(n,[["render",o]]);export{u as __pageData,b as default};
